function pathStem(path: string): string | null {
  const fileName = path.split('/').pop() ?? '';
  const stem = fileName.replace(/\.[^.]+$/, '').trim();
  if (stem.length < DETERMINISTIC_SEARCH_MIN_QUERY_LENGTH) {
